# Intended for sourcing by other shell scripts
# This file is automatically generated by fs-package

. "$BUILD_ENV_DIR/scripts/env.sh"
. "$BUILD_ENV_DIR/scripts/system.sh"

export PACKAGE_PREFIX="$BUILD_ENV_PREFIX"
# Deprecated:
export PREFIX="$BUILD_ENV_PREFIX"

export REINSTALL="$FSENV_REINSTALL"

# Runs cmake to configure a package (arguments: cmake's). On Linux and macOS, with the prefix as the
# install prefix, so that the installed .pc files (and the rpath in sdl3.pc) point to the env prefix
# and builds find the packages with pkg-config alone (the SDL3 overlay for development builds, see
# od-fs/configure). Without it, they say /usr/local: on macOS, FS-UAE then linked with
# -L/usr/local/lib ahead of the prefix, which on an Intel Mac with Homebrew (such as GitHub's
# runner) linked Homebrew's libraries, built for a newer macOS than the dist's minimum. The dists
# lose the absolute rpath (scripts/standalone.py). In cross mode (setup --host), also with the
# CMake toolchain file for the triplet.
package_cmake_configure() {
    if [ -n "$BUILD_ENV_HOST" ]; then
        cmake -DCMAKE_TOOLCHAIN_FILE="$BUILD_ENV_CMAKE_TOOLCHAIN" \
            -DCMAKE_INSTALL_PREFIX="$PACKAGE_PREFIX" "$@"
    elif [ "$SYSTEM_OS" = "Linux" ] || [ "$SYSTEM_OS" = "macOS" ]; then
        cmake -DCMAKE_INSTALL_PREFIX="$PACKAGE_PREFIX" "$@"
    else
        cmake "$@"
    fi
}

# The revision is part of the installed marker; without it, the marker ends in "-" and checks that
# expect <name>-<version>-<revision> do not find the package.
if [ -z "$PACKAGE_REVISION" ]; then
    echo "Error: the recipe for ${PACKAGE_NAME:-$PACKAGE} does not set PACKAGE_REVISION" >&2
    exit 1
fi

if [ "$PACKAGE_NAME" != "" ]; then
export INSTALLED="$PREFIX/installed/$PACKAGE_NAME-$PACKAGE_VERSION-$PACKAGE_REVISION"
else
export INSTALLED="$PREFIX/installed/$PACKAGE-$PACKAGE_REVISION"
fi

mkdir -p $PREFIX/installed

if test -e $INSTALLED ; then
if [ "$REINSTALL" != "1" ]; then
echo "$INSTALLED"
exit 0
fi
fi

echo
echo $PACKAGE

rm -Rf "$BUILD_ENV_PREFIX/_build"
mkdir "$BUILD_ENV_PREFIX/_build"
cd "$BUILD_ENV_PREFIX/_build"

if [ "$PACKAGE_URL" != "" ]; then
if [ "$PACKAGE_CHECKSUM" != "" ]; then
python3 "$BUILD_ENV_DIR/scripts/download.py" "$PACKAGE_URL" "$PACKAGE_CHECKSUM"
fi
fi
